const input = $input.first()?.json ?? {};
const body = input.body ?? input;

return [{
  json: {
    config: {
      companyName: body.companyName || 'ABM Solutions Demo',
      senderName: body.senderName || 'Demo Sender',
      senderEmail: body.senderEmail || 'demo@example.com',
      slackWebhookUrl: body.slackWebhookUrl || 'REPLACE_WITH_SLACK_WEBHOOK_URL',
      hubspotToken: body.hubspotToken || 'REPLACE_WITH_HUBSPOT_PRIVATE_APP_TOKEN',
      openAiApiKey: body.openAiApiKey || 'REPLACE_WITH_OPENAI_API_KEY',
      demoMode: body.demoMode !== false
    },
    payload: body
  }
}];

const root = $input.first().json;
const p = root.payload || {};
const isManualDemo = Object.keys(p).length === 0;

const submission = isManualDemo
  ? {
      name: 'Jamie Carter',
      email: 'jamie@example.com',
      company: 'Carter & Co',
      requestType: 'workflow_automation',
      problem: 'Manual lead intake creates delays and duplicate records.',
      desiredOutcome: 'Automated intake, CRM creation, and owner notification',
      deadline: new Date(Date.now() + 14 * 86400000).toISOString().slice(0, 10),
      budget: 5000
    }
  : {
      name: p.name,
      email: p.email,
      company: p.company,
      requestType: p.requestType,
      problem: p.problem,
      desiredOutcome: p.desiredOutcome,
      deadline: p.deadline,
      budget: Number(p.budget || 0)
    };

return [{ json: { ...root, submission } }];

const d=$input.first().json,s=d.submission;
const missing=['name','email','problem','desiredOutcome'].filter(k=>!s[k]);
if(missing.length) throw new Error(`Missing required fields: ${missing.join(', ')}`);
if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(s.email)) throw new Error('Invalid email.');
const days=Math.ceil((new Date(s.deadline)-Date.now())/86400000);
const urgency=days<=3?'critical':days<=7?'high':days<=21?'medium':'low';
return [{json:{...d,result:{intakeId:`INT-${Date.now()}`,status:'received',urgency,daysUntilDeadline:days,normalized:s,nextStep:'Discovery and solution scoping',createdAt:new Date().toISOString()}}}];
